mapper.codeEditorJavascript:
// ── Module 5 · Verdict ───────────────────────────────────────────────────────
// Decides whether the document may be processed, and where it belongs.
//
// Two checks, both strict on purpose:
// 1. Document type. A manual correction set in the Belegtyp field always wins -
//    the document only provides the suggestion when the field still reads
//    "Unbekannt".
// 2. Document date. The normalized date is recomposed and compared PURELY BY
//    STRING from the printed date. No parseDate, no time zone - an ISO date with
//    a zone would be read by Airtable as UTC and stored as the previous day.
//    If it does not add up, nothing is booked.

const parse = (v) => (typeof v === 'string' ? (v ? JSON.parse(v) : null) : v);

let x = {};
try { x = parse(input.extract) || {}; }
catch (e) { x = { _parseError: String(e && e.message || e) }; }

const ALLOWED = ['\u00dcbergabeprotokoll', '\u0052\u00fcckholprotokoll', 'Bestandsprotokoll'];

// ── Document type ────────────────────────────────────────────────────────────
const field = String(input.type_field || '').trim();
const suggestion = String(x.type || '').trim();
const type = (field && field !== 'Unbekannt' && ALLOWED.indexOf(field) >= 0)
  ? field
  : (ALLOWED.indexOf(suggestion) >= 0 ? suggestion : '');

// ── Document date ────────────────────────────────────────────────────────────
const raw = String(x.date_raw || '').trim();
const fmt = String(x.date_format || '').trim().toUpperCase();
const iso = String(x.date || '').trim();

let date = '';
let dateError = '';

if (!/^\d{4}-\d{2}-\d{2}$/.test(iso)) {
  dateError = 'Kein normalisiertes Belegdatum gelesen.';
} else if (Number(iso.slice(5, 7)) < 1 || Number(iso.slice(5, 7)) > 12 ||
           Number(iso.slice(8, 10)) < 1 || Number(iso.slice(8, 10)) > 31) {
  dateError = 'Belegdatum ausserhalb des gueltigen Bereichs: ' + iso + '.';
} else if (fmt === 'DD.MM.YYYY' && /^\d{2}\.\d{2}\.\d{4}$/.test(raw)) {
  const recomposed = raw.slice(6, 10) + '-' + raw.slice(3, 5) + '-' + raw.slice(0, 2);
  if (recomposed !== iso) {
    dateError = 'Belegdatum widerspruechlich: gedruckt ' + raw +
                  ', normalisiert ' + iso + ' (erwartet ' + recomposed + ').';
  } else {
    date = iso;
  }
} else if (fmt === 'YYYY-MM-DD' && raw === iso) {
  date = iso;
} else {
  dateError = 'Belegdatum nicht gegenpruefbar: gedruckt "' + raw +
                '" im Format "' + fmt + '".';
}

// ── Verdict ──────────────────────────────────────────────────────────────────
const problems = [];
if (x._parseError) problems.push('Antwort nicht lesbar: ' + x._parseError);
if (!type) problems.push('Belegart nicht eindeutig bestimmbar.');
if (dateError) problems.push(dateError);
if (x.note) problems.push(String(x.note));

const ok = problems.length === 0;

return {
  ok: ok ? 'yes' : 'no',
  document_type: type,
  document_date: date,
  target: ok ? (type === 'Bestandsprotokoll' ? 'inventory' : 'delivery') : '',
  note: problems.join(' '),
  document_number: String(input.document_number || '')
};
